    attribute led2State : Boolean := false;
    attribute prevBtn1 : Boolean := false;
    attribute prevBtn2 : Boolean := false;
    attribute prevBtn3 : Boolean := false;
    attribute debounceBtn1Ms : Integer := 0;
    attribute debounceBtn2Ms : Integer := 0;
    attribute debounceBtn3Ms : Integer := 0;
    attribute stableBtn1 : Boolean := false;
    attribute stableBtn2 : Boolean := false;
    attribute stableBtn3 : Boolean := false;
    attribute holdBtn1RemainingMs : Integer := 0;
    attribute holdBtn2RemainingMs : Integer := 0;
    attribute holdBtn3RemainingMs : Integer := 0;
    perform action tick {
      first start;
      then assign debounceBtn1Ms := (if io_2 ? debounceBtn1Ms + io_5 else 0);
      then assign stableBtn1 := (if io_2 ? debounceBtn1Ms >= 20 else false);
      then assign debounceBtn2Ms := (if io_3 ? debounceBtn2Ms + io_5 else 0);
      then assign stableBtn2 := (if io_3 ? debounceBtn2Ms >= 20 else false);
      then assign debounceBtn3Ms := (if io_4 ? debounceBtn3Ms + io_5 else 0);
      then assign stableBtn3 := (if io_4 ? debounceBtn3Ms >= 20 else false);
      then assign holdBtn1RemainingMs := (if holdBtn1RemainingMs > 0 ? holdBtn1RemainingMs - io_5 else 0);
      then assign holdBtn2RemainingMs := (if holdBtn2RemainingMs > 0 ? holdBtn2RemainingMs - io_5 else 0);
      then assign holdBtn3RemainingMs := (if holdBtn3RemainingMs > 0 ? holdBtn3RemainingMs - io_5 else 0);
      then if stableBtn3 and not prevBtn3 {
        first start;
        then assign led1State := false;
        then assign led2State := false;
        then assign holdBtn3RemainingMs := 2000;
      }
      then if not (holdBtn3RemainingMs > 0) and stableBtn1 and not prevBtn1 {
        first start;
        then assign led1State := not led1State;
        then assign holdBtn1RemainingMs := 2000;
      }
      then if not (holdBtn3RemainingMs > 0) and stableBtn2 and not prevBtn2 {
        first start;
        then assign led2State := not led2State;
        then assign holdBtn2RemainingMs := 2000;
      }
      then if holdBtn3RemainingMs > 0 {
        first start;
        then assign led1State := false;
        then assign led2State := false;
      }
      then if prevBtn1 != stableBtn1 {
        first start;
        then assign prevBtn1 := stableBtn1;
      } else {
        first start;
        then assign prevBtn1 := stableBtn1;
      }
      then if prevBtn2 != stableBtn2 {
        first start;
        then assign prevBtn2 := stableBtn2;
      } else {
        first start;
        then assign prevBtn2 := stableBtn2;
      }
      then if prevBtn3 != stableBtn3 {
        first start;
        then assign prevBtn3 := stableBtn3;
      } else {
        first start;
        then assign prevBtn3 := stableBtn3;
      }
    }
    out attribute io_0 : Boolean = led1State;
    out attribute io_1 : Boolean = led2State;
  }
